def handle(args, state, ds):
    report = ds.consistency_report()
    pending = report.get("pending", 0)
    checked = report.get("checked", 0)
    if pending == 0:
        return {
            "status": "complete",
            "aggregations_updated": checked,
            "pending_batches": 0,
            "metrics": {
                "engaged_users_count": "current",
                "traffic_source_count": "current",
                "total_visits_count": "current",
                "average_session_duration": "current"
            }
        }
    return {
        "status": "propagating",
        "aggregations_updated": checked,
        "pending_batches": pending,
        "metrics": {
            "engaged_users_count": "stale",
            "traffic_source_count": "stale",
            "total_visits_count": "stale",
            "average_session_duration": "stale"
        }
    }

